#!/usr/bin/env python3
"""Build a small, deterministic, evidence-first NFL price/results dashboard."""
from __future__ import annotations
import csv
import html
from pathlib import Path
import store
ROOT=Path(__file__).resolve().parent
DATA=ROOT/"data"
NAV=[("index.html","Overview"),("executive-summary.html","Executive summary"),("prices.html","Price snapshots"),("results.html","Official results"),("roi.html","ROI & backtests"),("questions.html","Questions"),("suggestions.html","Suggestions"),("flagged.html","Flagged for review"),("sources.html","Sources")]

def rows(name):
    with (DATA/name).open(newline="",encoding="utf-8") as f:return list(csv.DictReader(f))
def esc(s):return html.escape(str(s or ""),quote=True)
def anchor(url,label="Official source"):
    if not url:return '<span class="blank">—</span>'
    return f'<a href="{esc(url)}" rel="noopener noreferrer">{esc(label)} ↗</a>'
def table(data, columns, source_column=None, empty="No rows are available."):
    if not data:return f'<p class="empty">{esc(empty)}</p>'
    heads="".join(f"<th scope=\"col\">{esc(c.replace('_',' ').title())}</th>" for c in columns)
    body=[]
    for row in data:
        cells=[]
        for col in columns:
            val=row.get(col,"")
            if col==source_column: cells.append(f"<td>{anchor(val)}</td>")
            elif col=="flag_id" and val: cells.append(f'<td><a href="flagged.html#{esc(val)}">{esc(val)}</a></td>')
            else: cells.append(f"<td>{esc(val) if val else '—'}</td>")
        row_id = row.get("id", "")
        body.append(f'<tr id="{esc(row_id)}">'+"".join(cells)+"</tr>")
    return f'<div class="table-wrap"><table><thead><tr>{heads}</tr></thead><tbody>{"".join(body)}</tbody></table></div>'
def page(title, intro, content, active):
    nav="".join(f'<a class="{"active" if href==active else ""}" href="{href}">{esc(label)}</a>' for href,label in NAV)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="NFL source-provenanced price snapshots and official results feed"><title>{esc(title)} · NFL Price & Results Lab</title><link rel="stylesheet" href="style.css"></head><body><header class="top"><a class="brand" href="index.html">NFL Price &amp; Results Lab</a><span class="tag">Evidence-first · static research</span></header><nav aria-label="Main navigation">{nav}</nav><main><div class="eyebrow">NFL · DATA INFRASTRUCTURE</div><h1>{esc(title)}</h1><p class="intro">{intro}</p>{content}</main><footer><p>Static research snapshot. Not a live odds service, betting advice, or proof of strategy skill. Values are only used with row-level sources; missing evidence remains blank and flagged.</p><p>Data inherited from source-linked repository snapshots dated 2026-11-12 where stated. This subsite does not re-fetch or certify dynamic source pages.</p></footer></body></html>'''

def main():
    results=rows("official_results.csv"); quotes=rows("unclassified_market_quotes.csv")
    snapshots=rows("price_snapshots.csv"); settlements=rows("market_settlements.csv"); bets=rows("graded_bets.csv")
    pair_keys={tuple(item[k] for k in ("origin_id","event_id","market_type","market_id","selection_id","book","jurisdiction")):item["missing_phases"] for item in store.audit_snapshot_pairs(snapshots)}
    for item in snapshots:
        key=tuple(item[k] for k in ("origin_id","event_id","market_type","market_id","selection_id","book","jurisdiction"))
        item["pair_status"]="missing "+pair_keys[key] if key in pair_keys else "opening + closing present"
    flags=rows("flagged.csv")
    cards=[(str(len(results)),"source-linked final scores","No player-stat or market settlement rows are loaded."),(str(len(snapshots)),"opening / closing snapshot rows","No verified open/close records are currently present."),(str(len(settlements)),"market settlements","Settlement/ROI remains blocked until sourced and rule-qualified."),(str(len(quotes)),"legacy quote metadata rows","Price values are blank pending source re-verification.")]
    card_html="".join(f'<article class="card"><strong>{n}</strong><span>{esc(label)}</span><small>{esc(note)}</small></article>' for n,label,note in cards)
    overview=f'<section class="cards">{card_html}</section><section class="callout"><h2>Decision status</h2><p><strong>Do not interpret the current data as a validated betting edge.</strong> We have a row-linked historic final-score feed, but no qualifying open/close quote history and no sourced market settlements. ROI, closing-line value, prop-combo results and leaderboard rewards are therefore not reported.</p><p>For an auditable future pipeline: originate side first, then total, then moneyline; assign stable market/selection IDs; capture opening and a predeclared close in UTC; attach the official source and rule profile; keep signal metrics separate from staking outcomes.</p></section><section><h2>What is available</h2><ul><li>Official NFL game-result rows copied from the repository’s Week 1–9 result ledger; exact game source URL preserved on each row.</li><li>Existing DraftKings/FanDuel quote metadata is preserved separately. Historical price cells are blank because source captures/timestamps are unavailable; none are classified as opening/closing.</li><li>Append-only schemas and validation for future price snapshots and verified settlements.</li><li>Questions that block decisions, reviewable implementation suggestions and a nonblocking flagged register.</li></ul></section><section><h2>Top review blockers</h2>{table(flags[:4],["id","item","why_flagged","decision_impact","source_url"],"source_url")}</section>'
    (ROOT/"index.html").write_text(page("Overview","A source-provenanced store for NFL market snapshots, official game outcomes, and auditable backtests.",overview,"index.html"),encoding="utf-8")
    summary=f'<section class="cards">{card_html}</section><section class="callout"><h2>Bottom line</h2><p>Historical market prices cannot presently be used for opening/closing-line analysis: the 28 inherited quote rows have numeric values blanked because no retained quote capture was available for re-verification, their UTC capture times are blank, and an inherited DraftKings event URL currently returns 404 (F07). The new opening/closing store has zero observations.</p><p>The results feed contains {len(results)} inherited final-score rows with a direct NFL.com source URL and prior source-check date on each row. This session freshly checked a sample NFL game page, not all 136 pages; there are zero sourced market settlements and zero graded bets. Therefore ROI, CLV, prop-combo performance and a skill leaderboard are not computed.</p><p>Official references: {anchor("https://www.nfl.com/games/patriots-at-seahawks-2026-reg-1","NFL.com game center sample")} · {anchor("https://sportsbook.fanduel.com/navigation/nfl","FanDuel live market board")} · {anchor("https://www.fanduel.com/fanduel-sportsbook-house-rules-in","FanDuel Indiana rules example")}. The board is mutable; the rule page is jurisdiction-specific and neither supplies an applicable user jurisdiction by assumption.</p></section><section><h2>What is implemented</h2><ul><li>Append-only market snapshots with stable event/market/selection keys, phase, UTC timestamp, book, jurisdiction and source link.</li><li>Source-linked NFL game outcomes kept separate from book-specific settlements and ticket-level accepted odds.</li><li>Fail-closed settlement and ROI arithmetic; exact book/jurisdiction keys and source/rules references required.</li><li>Dedicated questions, reviewable suggestions and a Flagged for Review page.</li></ul></section><section><h2>Decisions / evidence still required</h2><ol><li>Select the legal operator and jurisdiction; persist its dated rules profile per wager.</li><li>Choose an authorized timestamped source or prospective capture method for opening, closing and interim prices; define the close cutoff.</li><li>Define a correction-aware official-results/stat feed and source retention policy.</li><li>Pre-register evaluation horizons, sample size, staking and demotion gates before rewards or live use.</li></ol><p>Until those inputs exist: no market edge, ROI or validated strategy is claimed. Review the {anchor("flagged.html","flagged register")} and {anchor("questions.html","decision questions")} before selecting a path.</p></section>'
    (ROOT/"executive-summary.html").write_text(page("Executive summary","Current evidence, deliverables, decision blockers and what is needed before any betting-performance decision.",summary,"executive-summary.html"),encoding="utf-8")
    price_content=f'<section class="callout"><h2>Opening and closing ledger</h2><p>Current verified snapshot rows: <strong>{len(snapshots)}</strong>. The store requires a UTC observation time, market/selection IDs, book, jurisdiction, price, odds and direct source evidence. No values are inferred from a date-only quote.</p><p>Opening/closing records: {table(snapshots,["origin_id","event_id","market_type","market_id","selection_id","phase","line","odds_american","book","jurisdiction","captured_at_utc","pair_status","source_url","verified_status","flag_id"],"source_url","No qualifying opening, intermediate or closing price snapshots are loaded.")}</p></section><section><h2>Inherited quote observations — not an open/close series</h2><p>These 28 metadata rows come from the existing Week 10 quote file. Numeric price cells are intentionally blank because no retained source capture permits re-verification; retrieval UTC times are also blank, so none can be classified as opening or closing prices. Rows are flagged F01 or F07.</p>{table(quotes,["week","date","away_team","home_team","book","away_spread","home_spread","total_points","away_moneyline_american","home_moneyline_american","retrieved_date","retrieved_time_utc","price_value_status","source_url","flag_id"],"source_url")}</section>'
    (ROOT/"prices.html").write_text(page("Price snapshots","A prospective, append-only market store. The empty ledger is intentional: no quote is assigned an opening or closing label without timestamp evidence.",price_content,"prices.html"),encoding="utf-8")
    result_content=f'<section class="callout"><p><strong>{len(results)} results</strong> from the existing 2026 Week 1–9 repository snapshot. These are official-source-linked final scores, not newly fetched today. Each row links to its exact NFL.com game page. Source revision/correction polling is not implemented.</p></section>{table(results,["event_id","week","date","away_team","home_team","away_points","home_points","status","official_source_url","source_verified_on","source_note"],"official_source_url")}'
    (ROOT/"results.html").write_text(page("Official results feed","A normalized, event-keyed feed of official-source-linked NFL final scores. Game results remain separate from sportsbook-specific settlement.",result_content,"results.html"),encoding="utf-8")
    roi_content=f'<section class="callout"><h2>ROI unavailable</h2><p>Eligible settled bets currently loaded: {len(bets)}. Verified market settlements loaded: {len(settlements)}. The evaluator refuses incomplete or unverified rows. A league final score alone does not determine every operator’s grading rules, especially props, parlays, postponements and voids.</p><p>When verified graded tickets exist, <code>python3 store.py roi</code> computes units staked, net units and ROI from accepted American odds, stake, sourced settlement and explicit settlement state. No ROI estimate is published from the current empty ledger.</p></section><h2>Market settlement records</h2>{table(settlements,["origin_id","event_id","market_type","market_id","selection_id","settlement","settled_at_utc","book","jurisdiction","rules_url","source_url","verified_status","flag_id"],"source_url","No market settlements loaded.")}<h2>Graded bet records</h2>{table(bets,["bet_id","origin_id","market_id","selection_id","book","jurisdiction","stake_units","accepted_odds_american","settlement","net_return_units","accepted_price_source_url","settlement_source_url","rules_url","verified_status","flag_id"],"settlement_source_url","No verified graded bets loaded.")}'
    (ROOT/"roi.html").write_text(page("ROI & backtests","Signal tests and staking outcomes must remain separate. This page reports no performance until accepted prices and verified settlements are present.",roi_content,"roi.html"),encoding="utf-8")
    q=rows("questions.csv"); content=f'<p>Questions below separate what the repository currently establishes from information still missing. Each answer is bounded to the linked official source or repository data; discovery steps are proposals, not claims that data is already available.</p>{table(q,["id","question","known_from_repo","missing_information","answer_now","next_discovery_step","official_source_url","status"],"official_source_url")}'
    (ROOT/"questions.html").write_text(page("Questions before decisions","Decision-readiness checklist: known facts, missing evidence, current answer, and a concrete discovery path.",content,"questions.html"),encoding="utf-8")
    s=rows("suggestions.csv"); content=f'<p>Suggestions are proposals for a reviewer to compare and choose before shared product changes. No suggestion below is marked approved or implemented beyond this isolated data prototype.</p>{table(s,["id","suggestion","decision_impact","tradeoff","recommended_path","status","source_url"],"source_url")}'
    (ROOT/"suggestions.html").write_text(page("Suggestions for review","A dedicated pre-implementation review section for improving decision quality. Select an option and its tradeoffs before integration work.",content,"suggestions.html"),encoding="utf-8")
    content=f'<p>Irregularities are nonblocking, but they block any claim that relies on the missing evidence. Blank values are intentional.</p>{table(flags,["id","item","why_flagged","current_value","decision_impact","next_step","source_url","severity"],"source_url")}'
    (ROOT/"flagged.html").write_text(page("Flagged for review","Unverified and incomplete items, with exact source links and the next verification step.",content,"flagged.html"),encoding="utf-8")
    src=rows("sources.csv"); content=f'<p>Official sources are linked directly. Operator rules listed here are jurisdiction-specific examples only, not a determination of applicable rules for any user.</p>{table(src,["id","source_name","source_type","scope","url","notes"],"url")}'
    (ROOT/"sources.html").write_text(page("Source register","League and operator sources used by this feed. Per-row result and quote tables retain their own direct links.",content,"sources.html"),encoding="utf-8")
    (ROOT/"style.css").write_text(CSS,encoding="utf-8")
    print("Built 9 pages from CSV source tables")

CSS='''
:root{--navy:#12253b;--blue:#2258a5;--cyan:#dcecf7;--ink:#1e2938;--muted:#596a7b;--line:#d8e0e8;--paper:#f6f8fb;--white:#fff;--amber:#fff3d9}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.55 system-ui,-apple-system,Segoe UI,Roboto,sans-serif}.top{background:var(--navy);color:white;padding:17px max(calc((100vw - 1200px)/2),24px);display:flex;justify-content:space-between;gap:15px;align-items:center}.brand{color:white;text-decoration:none;font-weight:750;letter-spacing:.01em}.tag{font-size:.83rem;color:#cfe2f3}nav{background:#1a3857;padding:0 max(calc((100vw - 1200px)/2),24px);display:flex;gap:5px;overflow:auto}nav a{color:#dbe8f5;padding:12px 13px;text-decoration:none;white-space:nowrap;font-size:.9rem}nav a:hover,nav a.active{background:#fff;color:var(--navy)}main{max-width:1200px;margin:36px auto;padding:0 24px 56px}.eyebrow{color:var(--blue);font-size:.76rem;letter-spacing:.13em;font-weight:800}h1{font-size:2.4rem;line-height:1.15;margin:8px 0 12px;color:var(--navy)}h2{font-size:1.35rem;color:var(--navy);margin:24px 0 12px}p.intro{max-width:850px;font-size:1.09rem;color:var(--muted);margin-bottom:28px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:25px 0}.card{background:white;border:1px solid var(--line);border-radius:10px;padding:18px;display:flex;flex-direction:column;gap:5px}.card strong{font-size:1.8rem;color:var(--blue)}.card span{font-weight:700}.card small{color:var(--muted);line-height:1.4}.callout{padding:17px 20px;border:1px solid #efdcae;background:var(--amber);border-radius:10px;margin:20px 0}.callout h2{margin-top:0}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:8px;background:white;margin:14px 0 26px}table{border-collapse:collapse;width:100%;font-size:.88rem}th,td{text-align:left;vertical-align:top;padding:10px 12px;border-bottom:1px solid var(--line);min-width:105px}th{background:#edf3f8;color:var(--navy);font-size:.78rem;position:sticky;top:0}td{max-width:360px}tr:last-child td{border:0}a{color:#174e91}td a{white-space:nowrap}.blank{color:#7a8794}code{background:#ecf0f4;padding:2px 5px;border-radius:3px}.empty{border:1px dashed #a7b4c0;border-radius:8px;padding:17px;background:white;color:var(--muted)}footer{border-top:1px solid var(--line);background:white;padding:18px max(calc((100vw - 1200px)/2),24px);color:var(--muted);font-size:.85rem}footer p{max-width:1200px;margin:6px auto}@media(max-width:760px){.cards{grid-template-columns:repeat(2,1fr)}h1{font-size:1.9rem}.top{align-items:flex-start;flex-direction:column}main{margin-top:24px;padding:0 16px 40px}nav{padding:0 10px}.table-wrap{margin-left:-4px;margin-right:-4px}}
'''
if __name__=="__main__":main()
